"use client";

import { useState, useEffect, CSSProperties, FormEvent, KeyboardEvent, MouseEvent, ReactNode } from "react";

// ─────────────────────────────────────────────────────────────────────────────
// CONSTANTS
// ─────────────────────────────────────────────────────────────────────────────

const PROGRAMS = ["cpe", "ie", "it", "is"];
const DOCUMENT_TYPES = ["Form 137", "Form 138", "Certificate of Enrollment"];
const PURPOSES = [
  "Scholarship Application",
  "Graduation Requirement",
  "Employment / Job Application",
  "Transfer to Another School",
  "Board Exam Application",
  "Government Requirement",
  "Personal Record",
  "Other",
];

type UserRole = "staff" | "student" | "unknown" | "invalid";
type AuthMethod = "google" | "password";
type RequestStatus = "Pending Approval" | "Processing" | "Approved" | "Rejected";

type PickupInfo = {
  date?: string;
  time?: string;
  location?: string;
  notes?: string;
};

type RequestItem = {
  id: number | string;
  type: string;
  status: RequestStatus;
  date: string;
  student?: string;
  studentName?: string;
  studentProgram?: string;
  studentNumber?: string;
  purpose?: string;
  copies: number;
  pickupDetails: PickupInfo | null;
};

type RegisteredUser = {
  email: string;
  fullName: string;
  role: "staff" | "student";
  program?: string;
  authMethod?: AuthMethod;
  password?: string | null;
  icon?: string;
};

type NotificationItem = {
  id: number;
  msg: string;
  time: string;
  read: boolean;
};

type ChartDatum = { label: string; value: number };
type DonutSegment = { label: string; value: number; color: string };

function detectRole(email: string): { role: "staff" | "student" | "invalid"; label: string; icon: string; program?: string } | null {
  const lower = email.toLowerCase().trim();
  if (!lower.includes("@gmail.com")) return null;
  const local = lower.split("@")[0];
  const parts = local.split(".");
  if (parts.length < 2) return null;
  const prefix = parts[0];
  if (prefix === "admin") return { role: "staff", label: "Staff / Registrar", icon: "🏫" };
  if (PROGRAMS.includes(prefix)) return { role: "student", label: `Student (${prefix.toUpperCase()})`, icon: "🎓", program: prefix };
  return { role: "invalid", label: "Invalid", icon: "❌" };
}

// ─────────────────────────────────────────────────────────────────────────────
// PERSISTENT STORAGE — localStorage + in-memory fallback
// ─────────────────────────────────────────────────────────────────────────────

const _mem = new Map<string, unknown>();

function stGet<T>(key: string, fallback: T): T {
  try {
    if (typeof window !== "undefined") {
      const raw = window.localStorage.getItem(key);
      if (raw !== null) return JSON.parse(raw) as T;
    }
  } catch {}
  return _mem.has(key) ? (_mem.get(key) as T) : fallback;
}

function stSet<T>(key: string, val: T) {
  _mem.set(key, val);
  try {
    if (typeof window !== "undefined") window.localStorage.setItem(key, JSON.stringify(val));
  } catch {}
}

// ─────────────────────────────────────────────────────────────────────────────
// PDF GENERATION
// ─────────────────────────────────────────────────────────────────────────────

function normalizeRequest(row: any, fallbackStudent = ""): RequestItem {
  const createdAt = row?.created_at || row?.date;
  return {
    id: row?.id,
    type: row?.document_type || row?.type || "Form 137",
    status: (row?.status as RequestStatus) || "Pending Approval",
    date: createdAt ? new Date(createdAt).toLocaleDateString("en-PH", { dateStyle: "medium", timeStyle: "short" }) : row?.date || "",
    student: row?.student || row?.student_name || fallbackStudent,
    studentProgram: row?.student_program || row?.studentProgram || "",
    studentName: row?.student_name || row?.studentName || row?.student || fallbackStudent,
    studentNumber: row?.student_number || row?.studentNumber || "",
    purpose: row?.purpose || "",
    copies: Number(row?.copies || 1),
    pickupDetails: (row?.pickup_details || row?.pickupDetails) ?? null,
  };
}

